import { existsSync, mkdirSync, readFileSync, writeFileSync, renameSync, unlinkSync, lstatSync } from "node:fs"
import { Database } from "bun:sqlite"
import { join, resolve } from "node:path"
import { parseArgs } from "node:util"
import { SoulStore } from "./store"
import { acquireHostLock, listCheckpoints } from "./checkpoint"
import { startEngine } from "./engine"
import { OpenCodeAdapter } from "./adapter"
import { startServer, ModelConfigurationError } from "./server"
import { PRODUCT_VERSION, isSupportedSchema, type CheckpointInfo } from "./contracts"
import { mountPortable } from "./portable"
import { backupEngine } from "./engine-backup"
import { resumeProductRestore, restoreProduct } from "./recovery"

export async function main(args = process.argv.slice(2)) {
  const { values } = parseArgs({ args, options: {
    "portable-root": { type: "string" }, "host-root": { type: "string" }, engine: { type: "string" }, project: { type: "string" }, port: { type: "string" },
    "recovery-generation": { type: "string" },
    "no-open": { type: "boolean" }, "offline": { type: "boolean" }, version: { type: "boolean" }, help: { type: "boolean" },
  } })
  if (values.version) { console.log(`星杳 · 璇玑 ${PRODUCT_VERSION}`); return }
  if (values.help) { console.log("xingyao --portable-root <directory> [--engine <opencode.exe>] [--project <directory>] [--no-open] [--offline]"); return }
  const portable = resolve(values["portable-root"] ?? process.env.XUANJI_ROOT ?? join(process.cwd(), "Xuanji"))
  mkdirSync(portable, { recursive: true })
  const marker = join(portable, "drive.json")
  if (!existsSync(marker)) writeFileSync(marker, JSON.stringify({ driveId: crypto.randomUUID(), product: "xingyao-xuanji", version: 1 }), { flag: "wx" })
  const drive: unknown = JSON.parse(readFileSync(marker, "utf8"))
  if (!drive || typeof drive !== "object" || !("driveId" in drive) || typeof drive.driveId !== "string" || !/^[0-9a-f-]{36}$/.test(drive.driveId)) throw new Error("便携身份标识无效，停止启动以保护数据")
  const host = resolve(values["host-root"] ?? join(process.env.LOCALAPPDATA ?? join(process.env.USERPROFILE ?? process.cwd(), "AppData", "Local"), "Xuanji", drive.driveId))
  mkdirSync(host, { recursive: true })
  if (await reopenExisting(host, drive.driveId, values["no-open"] === true)) return
  const unlock = acquireHostLock(host)
  const vault = join(portable, "vault")
  const dbPath = join(host, "soul.db")
  let store: SoulStore | undefined
  let engine: Awaited<ReturnType<typeof startEngine>> | undefined
  let app: ReturnType<typeof startServer> | undefined
  let stopping = false
  let maintenanceTimer: ReturnType<typeof setInterval> | undefined
  let mount: ReturnType<typeof mountPortable> | undefined
  try {
    const executable = resolve(values.engine ?? join(portable, "system", "engine", "opencode.exe"))
    const probe = existsSync(executable) ? Bun.spawnSync([executable, "--version"], { stdout: "pipe", stderr: "ignore", windowsHide: true, timeout: 10_000 }) : null
    const executableVersion = probe?.exitCode === 0 ? probe.stdout.toString().trim() : ""
    if (!values.offline && probe && !/^[A-Za-z0-9][A-Za-z0-9.+_-]{0,127}$/.test(executableVersion)) throw new Error("无法核实所选引擎版本，尚未打开身份或引擎数据库")
    const executableHash = existsSync(executable) ? new Bun.CryptoHasher("sha256").update(await Bun.file(executable).arrayBuffer()).digest("hex") : ""
    const recoveryOptions = { hostDir: host, vaultDir: vault, engineVersion: executableVersion }
    const resumed = await resumeProductRestore(recoveryOptions)
    const snapshots = await listCheckpoints(vault)
    const heads = snapshots.filter(snapshot => !snapshots.some(other => other.parent === snapshot.generation))
    if (heads.length > 1) throw new Error("U 盘存在多个恢复分支，请先选择要恢复的检查点；未覆盖任何数据")
    const latest = heads[0]
    // Branch decisions must use the committed state *before* SoulStore performs
    // its forward migration. A schema repair legitimately changes the revision;
    // it must not turn a clean older host into a fictitious unsynced branch.
    const before = readHostState(dbPath)
    if (latest && before && before.identityId !== latest.identityId) throw new Error("宿主和 U 盘身份不同，停止自动同步")
    const recoveryGeneration = values["recovery-generation"]
    if (recoveryGeneration && before?.generation !== recoveryGeneration) throw new Error("恢复分支和选定代次不一致，停止自动启动")
    if (recoveryGeneration && !hasPairedRestoreAncestor(before, resumed.generation, snapshots)) {
      const selected = snapshots.find(snapshot => snapshot.generation === recoveryGeneration)
      if (!selected || selected.identityId !== before?.identityId || selected.revision !== before.revision || selected.schemaVersion !== before.schemaVersion)
        throw new Error("恢复分支已有新工作，需先核实配套引擎状态，不能重新覆盖")
      await restoreProduct({ ...recoveryOptions, generation: recoveryGeneration })
    }
    if (latest && !recoveryGeneration && !before) await restoreProduct({ ...recoveryOptions, generation: latest.generation })
    else if (latest && !recoveryGeneration && before && before.generation !== latest.generation) {
      const parent = snapshots.find(snapshot => snapshot.generation === before.generation)
      const clean = parent && before.revision === parent.revision && before.schemaVersion === parent.schemaVersion
      if (!clean) throw new Error(`检测到宿主未同步分支。活动库保留在 ${dbPath}；U 盘检查点未覆盖。请通过恢复流程选择分支。`)
      await restoreProduct({ ...recoveryOptions, generation: latest.generation })
    }
    // Re-read after a paired restore, before opening/migrating the domain store.
    // An existing host must not bypass the version checks used for checkpoints.
    const prepared = readHostState(dbPath)
    if (!values.offline && executableVersion) assertEngineBinding(host, prepared?.engineVersion ?? "", prepared?.engineSha256 ?? "", executableVersion, executableHash)
    store = new SoulStore(dbPath)
    const savedBase = snapshots.find(snapshot => snapshot.generation === store!.meta("checkpoint_generation"))
    if (savedBase && savedBase.identityId === store.identityId && store.revision >= savedBase.revision) store.setMeta("checkpoint_revision", String(savedBase.revision))
    store.recoverInterrupted()
    if (!values.project && !values.offline) mount = mountPortable(portable)
    const project = resolve(values.project ?? join(mount?.root ?? portable, "projects", "default"))
    mkdirSync(project, { recursive: true })
    const configPath = join(host, "engine-config.json")
    if (!existsSync(configPath)) writeFileSync(configPath, JSON.stringify({ "$schema": "https://opencode.ai/config.json" }, null, 2), { flag: "wx" })
    // Every entry point, including model reconfiguration and its recovery,
    // checks the same selected binary. Offline inspection never launches one.
    const launchSelected = async (selectedConfig: string) => {
      if (values.offline || !executableVersion) throw new Error("当前启动方式没有可核实的执行引擎")
      assertEngineBinding(host, store!.meta("engine_version"), store!.meta("engine_sha256"), executableVersion, executableHash)
      const currentHash = new Bun.CryptoHasher("sha256").update(await Bun.file(executable).arrayBuffer()).digest("hex")
      if (currentHash !== executableHash) throw new Error("启动后引擎程序发生变化，请退出并核实发行")
      const selected = await startEngine({ executable, hostDir: host, projectDir: project, configPath: selectedConfig })
      if (selected.version !== executableVersion) { await selected.stop(); throw new Error("引擎服务版本与启动前版本探测不符") }
      return selected
    }

